//! Two fixed standalone Service cases; no production hooks or permission claim.
use pokelinux_connectivity_control::{kernel::Fact,owner::{Action,Authority,Phase,Principal},service::{Service,Snapshot}};
use pokelinux_network_state::boot_time_ns;
use serde_json::{Value,json};
use std::{env,fs::{self,File},io,os::unix::{fs::{DirBuilderExt,MetadataExt},process::ExitStatusExt},panic::{self,AssertUnwindSafe},path::{Path,PathBuf},thread,time::Duration};
const MS:u64=1_000_000;
fn publish(root:&Path,name:&str,value:Value){let temporary=root.join(format!("{name}.tmp"));fs::write(&temporary,serde_json::to_vec(&value).unwrap()).unwrap();fs::rename(temporary,root.join(name)).unwrap();}
fn fact(f:Fact)->Value{json!({"namespace":{"dev":f.namespace.dev,"ino":f.namespace.ino},"ifindex":f.ifindex,"lifetime":f.lifetime,"connected":f.connected})}
fn snapshot(s:Snapshot)->Value{json!({"worker":s.worker.map(|id|id.hex()),"ready":s.ready,"fact":s.fact.map(fact),"observed_at_ns":s.observed_at_ns,"owner_pending":s.owner.pending.map(|p|json!({"id":p.command.id.0,"phase":format!("{:?}",p.phase),"original_until_ns":p.command.original_until_ns})),"owner_observed":s.owner.observed.map(|o|json!({"connected":o.connected,"observed_at_ns":o.observed_at_ns})),"owner_terminal_uncertain":s.owner.terminal_uncertain,"terminal_uncertain":s.terminal_uncertain,"stopping":s.stopping,"output_eof":s.output_eof,"reaped":s.reaped,"occupied":s.occupied,"namespace_handles_open":s.namespace_handles_open,"main_caps_dropped":s.main_caps_dropped,"exit_status":s.exit_status.map(|status|json!({"code":status.code(),"signal":status.signal(),"success":status.success()}))})}
fn auth()->Authority{Authority{principal:Principal{instance:301,generation:7},permission_epoch:11,allowed:true}}
fn caps()->Value{let text=fs::read_to_string("/proc/self/status").unwrap();let mut out=serde_json::Map::new();for name in ["CapEff","CapPrm","CapBnd","CapInh","CapAmb","NoNewPrivs"]{let prefix=format!("{name}:");let raw=text.lines().find(|line|line.starts_with(&prefix)).unwrap().split_whitespace().nth(1).unwrap();if name=="NoNewPrivs"{assert_eq!(raw,"1");}else{assert_eq!(u64::from_str_radix(raw,16).unwrap(),0);}out.insert(name.to_owned(),json!(raw));}Value::Object(out)}
fn namespace_files()->Value{let mut out=Vec::new();for entry in fs::read_dir("/proc/self/fd").unwrap(){let path=entry.unwrap().path();match fs::read_link(&path){Ok(target)if target.to_string_lossy().starts_with("net:[")=>{let m=fs::metadata(&path).unwrap();out.push(json!({"fd":path.file_name().unwrap().to_string_lossy(),"target":target.to_string_lossy(),"dev":m.dev(),"ino":m.ino()}));},Ok(_)=>{},Err(e)if e.kind()==io::ErrorKind::NotFound=>{},Err(e)=>panic!("namespace descriptor inventory: {e}")}}json!(out)}
fn retained(inventory:&Value,current:Fact,peer:(u64,u64)){let a=inventory.as_array().unwrap();assert!(a.iter().any(|v|v["dev"]==current.namespace.dev&&v["ino"]==current.namespace.ino));assert!(a.iter().any(|v|v["dev"]==peer.0&&v["ino"]==peer.1));}
fn bounded_snapshot(service:&mut Service)->Snapshot{let start=boot_time_ns();let value=service.snapshot();assert!(boot_time_ns()-start<100*MS,"SNAPSHOT_MUST_REMAIN_RESPONSIVE");value}
fn poll(service:&mut Service)->Snapshot{let start=boot_time_ns();service.poll().unwrap();let value=bounded_snapshot(service);assert!(boot_time_ns()-start<100*MS,"MAIN_POLL_MUST_REMAIN_RESPONSIVE");value}
fn gate(service:&mut Service,root:&Path,name:&str,end:u64,io_allowed:bool)->Value{while boot_time_ns()<end{if io_allowed{poll(service);}else{bounded_snapshot(service);}match fs::read(root.join(name)){Ok(data)=>return serde_json::from_slice(&data).unwrap(),Err(e)if e.kind()==io::ErrorKind::NotFound=>thread::sleep(Duration::from_millis(2)),Err(e)=>panic!("gate {name}: {e}")}}panic!("original cutoff waiting for {name}");}
fn same_worker(s:Snapshot,original:Fact,worker:&str){assert_eq!(s.worker.map(|id|id.hex()).as_deref(),Some(worker));if let Some(f)=s.fact{assert_eq!((f.namespace,f.ifindex,f.lifetime),(original.namespace,original.ifindex,original.lifetime));assert!(!f.connected);}assert!(s.namespace_handles_open);}
fn setup(service:&mut Service,root:&Path,case:u64,peer:(u64,u64))->(Fact,String,Value){let end=case.min(boot_time_ns()+1_000*MS);let initial=loop{let s=poll(service);if s.ready{break s;}assert!(boot_time_ns()<end&&!s.stopping,"actual startup must become Ready");thread::sleep(Duration::from_millis(2));};assert!(initial.main_caps_dropped);let original=initial.fact.unwrap();assert!(!original.connected);let worker=initial.worker.unwrap().hex();let inventory=namespace_files();retained(&inventory,original,peer);publish(root,"created.json",json!({"pid":std::process::id(),"worker_pid":service.child_pid().unwrap(),"worker":worker,"fact":fact(original),"main_caps":caps(),"actual_namespace_fd_inventory":inventory,"created_at_ns":boot_time_ns(),"snapshot":snapshot(initial)}));let ready=gate(service,root,"ready.json",case,true);for key in ["provisioner_reaped_before_packet_peer","supervisor_all_caps_zero","packet_peer_all_caps_zero","Main_all_caps_zero","worker_NET_ADMIN_only"]{assert_eq!(ready[key],true);}let before=poll(service);same_worker(before,original,&worker);assert!(before.ready&&before.fact.is_some()&&before.owner.observed.is_some());publish(root,"request-stop-worker.json",json!({"worker_pid":service.child_pid().unwrap(),"worker":worker,"requested_at_ns":boot_time_ns(),"snapshot":snapshot(before)}));let stopped=gate(service,root,"worker-stopped.json",case,true);assert_eq!(stopped["worker_pid"],service.child_pid().unwrap());assert_eq!(stopped["worker"],worker);assert_eq!(stopped["actual_pidfd_SIGSTOP"],true);assert!(matches!(stopped["state"].as_str(),Some("T"|"t")));(original,worker,stopped)}
fn expiry(service:&mut Service,root:&Path,case:u64,peer:(u64,u64))->Value{let(original,worker,stopped)=setup(service,root,case,peer);let start=boot_time_ns();let action_until=start+100*MS;let hold_until=start+350*MS;let resume_until=start+450*MS;let independent_until=start+1_250*MS;assert!(independent_until<case,"all held/late observation cutoffs fit original case before dispatch");let authority=auth();let id=service.submit(authority,Action::Connect,action_until).unwrap();let dispatched=bounded_snapshot(service);same_worker(dispatched,original,&worker);let pending=dispatched.owner.pending.unwrap();assert_eq!(pending.phase,Phase::Dispatched);assert_eq!(pending.command.id,id);assert_eq!(pending.command.original_until_ns,action_until);assert!(stopped["observed_at_ns"].as_u64().unwrap()<=start);publish(root,"dispatch.json",json!({"id":id.0,"started_at_ns":start,"original_until_ns":action_until,"original_hold_until_ns":hold_until,"original_resume_until_ns":resume_until,"original_independent_until_ns":independent_until,"stopped":stopped,"snapshot":snapshot(dispatched)}));
    // Snapshot-only window: no poll, reply receive, file read or network I/O.
    let mut samples=Vec::new();while boot_time_ns()<hold_until{let before=boot_time_ns();let s=bounded_snapshot(service);same_worker(s,original,&worker);assert!(s.occupied&&!s.reaped&&!s.output_eof);let p=s.owner.pending.unwrap();assert_eq!(p.command.id,id);assert_eq!(p.phase,Phase::Dispatched);assert_eq!(p.command.original_until_ns,action_until);if let Some(at)=s.observed_at_ns{assert!(at<=stopped["observed_at_ns"].as_u64().unwrap());}if let Some(o)=s.owner.observed{assert!(!o.connected&&o.observed_at_ns<=stopped["observed_at_ns"].as_u64().unwrap());}samples.push(json!({"before_ns":before,"after_ns":boot_time_ns(),"snapshot":snapshot(s)}));assert!(samples.len()<512);thread::sleep(Duration::from_millis(2));}
    let expired=bounded_snapshot(service);let sampled_at=boot_time_ns();assert!(sampled_at>=hold_until&&sampled_at-start>250*MS);assert!(expired.terminal_uncertain&&!expired.ready);publish(root,"expiry-before-assert.json",json!({"snapshot":snapshot(expired),"sampled_at_ns":sampled_at,"snapshot_only_started_at_ns":start,"original_until_ns":action_until,"original_hold_until_ns":hold_until,"original_resume_until_ns":resume_until,"original_independent_until_ns":independent_until,"samples":samples}));assert!(expired.fact.is_none()&&expired.observed_at_ns.is_none(),"EXPIRED_TOP_OBSERVATION_MUST_BE_NONE");assert!(expired.owner.observed.is_none(),"EXPIRED_OWNER_OBSERVATION_MUST_BE_NONE");assert!(service.take_reply(id,authority).is_none(),"EXPIRED_REQUEST_MUST_NOT_PUBLISH_REPLY");publish(root,"resume-worker.json",json!({"worker":worker,"requested_at_ns":boot_time_ns(),"original_resume_until_ns":resume_until,"original_independent_until_ns":independent_until}));let resumed=gate(service,root,"worker-resumed.json",resume_until,false);assert_eq!(resumed["actual_pidfd_SIGCONT"],true);assert!(resumed["signal_at_ns"].as_u64().unwrap()>=hold_until);let mut after_samples=Vec::new();while boot_time_ns()<independent_until{let s=poll(service);same_worker(s,original,&worker);assert!(s.terminal_uncertain&&!s.ready,"expired epoch must never reopen");assert!(service.take_reply(id,authority).is_none(),"LATE_REPLY_MUST_NOT_PUBLISH");if after_samples.len()<512{after_samples.push(json!({"at_ns":boot_time_ns(),"snapshot":snapshot(s)}));}thread::sleep(Duration::from_millis(2));}publish(root,"independent-finish-request.json",json!({"requested_at_ns":boot_time_ns(),"original_independent_until_ns":independent_until}));let independent=gate(service,root,"independent-absence.json",case,true);assert_eq!(independent["ipv4"],json!([]));assert_eq!(independent["target_address_notifications"],json!([]));assert_eq!(independent["actual_final_EAGAIN"],true);assert!(service.take_reply(id,authority).is_none());let inventory=namespace_files();retained(&inventory,original,peer);json!({"passed":true,"case":"expiry","fixture_authority_only":true,"Settings_window_executed":false,"same_worker":worker,"original_fact":fact(original),"dispatch":snapshot(dispatched),"expired_snapshot":snapshot(expired),"worker_resumed":resumed,"late_snapshots":after_samples,"independent_absence":independent,"actual_namespace_fd_inventory":inventory,"original_case_until_ns":case,"completed_at_ns":boot_time_ns()})}
fn stop_case(service:&mut Service,root:&Path,case:u64,peer:(u64,u64))->Value{let(original,worker,stopped)=setup(service,root,case,peer);let ready=bounded_snapshot(service);assert!(ready.occupied&&ready.ready&&!ready.output_eof&&!ready.reaped);let authority=auth();let started=boot_time_ns();let action_until=started+100*MS;assert!(action_until<case,"original100ms Stop-case action fits original case before dispatch");let id=service.submit(authority,Action::Connect,action_until).unwrap();let before=bounded_snapshot(service);same_worker(before,original,&worker);let pending=before.owner.pending.unwrap();assert_eq!(pending.phase,Phase::Dispatched);assert_eq!(pending.command.id,id);assert_eq!(pending.command.original_until_ns,action_until);assert!(before.occupied&&before.ready&&!before.output_eof&&!before.reaped);assert!(stopped["observed_at_ns"].as_u64().unwrap()<=started);let dispatched_at=boot_time_ns();assert!(dispatched_at<action_until);publish(root,"stop-dispatch.json",json!({"id":id.0,"action":"Connect","started_at_ns":started,"dispatched_at_ns":dispatched_at,"original_until_ns":action_until,"worker":worker,"worker_stopped":stopped,"snapshot":snapshot(before)}));
    // No poll or worker consume after enqueue: Stop owns this outstanding command.
    let began=boot_time_ns();assert!(began<action_until,"Stop must start with original outstanding deadline still live");service.stop().unwrap();let immediate=bounded_snapshot(service);let returned=boot_time_ns();publish(root,"stop-before-assert.json",json!({"before":snapshot(before),"immediate":snapshot(immediate),"dispatch_id":id.0,"original_action_until_ns":action_until,"stop_called_at_ns":began,"stop_returned_at_ns":returned,"worker_stopped":stopped}));assert!(returned-began<100*MS,"STOP_MUST_REMAIN_RESPONSIVE");same_worker(immediate,original,&worker);assert!(immediate.stopping&&immediate.terminal_uncertain&&!immediate.ready);assert!(immediate.occupied&&!immediate.reaped&&!immediate.output_eof&&immediate.exit_status.is_none(),"STOP_MUST_RETAIN_UNREAPED_CHILD_AND_OUTPUT");assert!(immediate.fact.is_none()&&immediate.observed_at_ns.is_none(),"STOP_TOP_OBSERVATION_MUST_BE_NONE");assert!(immediate.owner.observed.is_none(),"STOP_OWNER_OBSERVATION_MUST_BE_NONE");assert!(service.take_reply(id,authority).is_none(),"STOP_MUST_FENCE_OUTSTANDING_REPLY");while service.occupied()&&boot_time_ns()<case{let s=poll(service);same_worker(s,original,&worker);assert!(!s.ready);assert!(service.take_reply(id,authority).is_none(),"STOP_MUST_FENCE_OUTSTANDING_REPLY");thread::sleep(Duration::from_millis(2));}let last=bounded_snapshot(service);assert!(!last.occupied&&last.reaped&&last.output_eof);assert_eq!(last.exit_status.unwrap().signal(),Some(9));assert!(service.take_reply(id,authority).is_none());let inventory=namespace_files();retained(&inventory,original,peer);publish(root,"independent-finish-request.json",json!({"requested_at_ns":boot_time_ns()}));let independent=gate(service,root,"independent-absence.json",case,true);assert_eq!(independent["ipv4"],json!([]));assert_eq!(independent["target_address_notifications"],json!([]));assert_eq!(independent["actual_final_EAGAIN"],true);json!({"passed":true,"case":"stop","fixture_authority_only":true,"Settings_window_executed":false,"same_worker":worker,"original_fact":fact(original),"outstanding_dispatch_id":id.0,"original_action_until_ns":action_until,"immediate_stop":snapshot(immediate),"after_actual_wait_EOF":snapshot(last),"independent_absence":independent,"actual_namespace_fd_inventory":inventory,"original_case_until_ns":case,"completed_at_ns":boot_time_ns()})}
fn main(){assert_eq!(env::var("POKELINUX_CONNECTIVITY_ISOLATED").as_deref(),Ok("1"));let args:Vec<_>=env::args().skip(1).collect();assert_eq!(args.len(),6,"case worker-elf gates peer-ns case-until close-until");assert!(matches!(args[0].as_str(),"expiry"|"stop"));let root=PathBuf::from(&args[2]);let case:u64=args[4].parse().unwrap();let close:u64=args[5].parse().unwrap();let start=boot_time_ns();assert!(start<case&&case-start<=6_000*MS&&case<close);let m=fs::metadata(&args[3]).unwrap();let peer=(m.dev(),m.ino());let journal=root.join("journal");fs::DirBuilder::new().mode(0o700).create(&journal).unwrap();let mut service=Service::start(Path::new(&args[1]),File::open(&args[3]).unwrap(),journal.join("admitted"),case.min(boot_time_ns()+1_000*MS)).unwrap();let desired=panic::catch_unwind(AssertUnwindSafe(||match args[0].as_str(){"expiry"=>expiry(&mut service,&root,case,peer),"stop"=>stop_case(&mut service,&root,case,peer),_=>unreachable!()}));let before_stop=snapshot(service.snapshot());let mut errors=Vec::new();if !service.snapshot().stopping{if let Err(e)=service.stop(){errors.push(format!("stop: {e}"));}}let immediate=snapshot(service.snapshot());while service.occupied()&&boot_time_ns()<close{if let Err(e)=service.poll(){errors.push(format!("closure poll: {e}"));break;}thread::sleep(Duration::from_millis(2));}let last=service.snapshot();let inventory=namespace_files();let closed=!last.occupied&&last.reaped&&last.output_eof&&last.exit_status.is_some_and(|status|status.signal()==Some(9))&&last.namespace_handles_open&&boot_time_ns()<close&&errors.is_empty();publish(&root,"service-closure.json",json!({"closed":closed,"before_stop":before_stop,"immediate_after_stop":immediate,"after_actual_wait_EOF":snapshot(last),"actual_namespace_fd_inventory":inventory,"original_close_until_ns":close,"completed_at_ns":boot_time_ns(),"errors":errors}));let passed=desired.is_ok()&&closed;match desired{Ok(value)=>publish(&root,"passed.json",value),Err(error)=>{let message=error.downcast_ref::<String>().cloned().or_else(||error.downcast_ref::<&str>().map(|v|v.to_string())).unwrap_or_else(||"non-string panic".to_owned());publish(&root,"failed.json",json!({"message":message,"closed":closed,"failed_at_ns":boot_time_ns()}));}}println!("{}",json!({"passed":passed,"case":args[0],"service_closed":closed}));if !closed{std::process::abort();}drop(service);std::process::exit(if passed{0}else{101});}
